import{_ as t,o,c as s,a2 as a}from"./chunks/framework.uw_ZoRon.js";const u=JSON.parse('{"title":"Epoch preemption","description":"","frontmatter":{},"headers":[],"relativePath":"deep-dive/epoch-preemption.md","filePath":"deep-dive/epoch-preemption.md"}'),r={name:"deep-dive/epoch-preemption.md"};function n(i,e,h,p,c,d){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="epoch-preemption" tabindex="-1">Epoch preemption <a class="header-anchor" href="#epoch-preemption" aria-label="Permalink to &quot;Epoch preemption&quot;">​</a></h1><p>Tokio scheduling is <strong>cooperative</strong> — a task only yields when it <code>await</code>s. That&#39;s a problem for untrusted guests: a tight <code>loop {}</code> with no host calls would never yield, hogging a worker thread and starving every other process. The BEAM solves this by counting &quot;reductions&quot; and preempting. RUSM solves it with <strong>Wasmtime epoch interruption</strong> — fair scheduling even when a guest never cooperates.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>Wasmtime compiles guest code with periodic <strong>epoch checks</strong>. A <strong>dedicated background thread</strong> bumps a global epoch counter on a fixed cadence (~10 ms) — on its own thread so a CPU-pinned guest can&#39;t starve the bump itself; when a running guest crosses an epoch boundary, Wasmtime interrupts it. RUSM yields the fiber back to the scheduler (see <a href="/rusm/deep-dive/fibers-and-blocking-to-async">fibers &amp; blocking→async</a>) and resumes it later. The upshot: even an infinite loop yields its fair share of the CPU.</p><h2 id="why-epochs-not-fuel" tabindex="-1">Why epochs, not fuel <a class="header-anchor" href="#why-epochs-not-fuel" aria-label="Permalink to &quot;Why epochs, not fuel&quot;">​</a></h2><p>Wasmtime also offers <strong>fuel</strong> — decrement a counter per instruction — but epoch interruption is far cheaper at runtime: one periodic counter check versus per-instruction accounting. On a hot path juggling hundreds of thousands of processes, that difference matters.</p><h2 id="the-test-that-proves-it" tabindex="-1">The test that proves it <a class="header-anchor" href="#the-test-that-proves-it" aria-label="Permalink to &quot;The test that proves it&quot;">​</a></h2><p>Phase 6 ships a <strong>fairness</strong> test: spawn a process running an infinite loop alongside others that must keep making progress — still receiving messages, say. With epoch interruption on, the bystanders are never starved. The dashboard&#39;s fairness scenario shows the same thing live, with bystanders holding 50M+ ops/sec under a tight-loop spinner.</p><blockquote><p>Shipped in Phase 6 (requires the Wasmtime backend).</p></blockquote>',9)])])}const m=t(r,[["render",n]]);export{u as __pageData,m as default};
